style.css:
@-moz-document domain("gemini.google.com") {
/* Fondo principal y colores base */
    body, .app-root {
        background-image: url("https://i.imgur.com/834f3P0.jpg") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-color: #0b0b0b !important;
        color: #ffffffe3 !important;
    }

    /* Efecto de cristal para paneles principales */
    .main-content,
    .chat-history,
    .input-area-container,
    .response-container,
    .query-container,
    .mat-drawer-inner-container,
    .welcome-container,
    .card,
    .header,
    .upload-dialog {
        background: linear-gradient(135deg, #0000004f, #00000069) !important;
        backdrop-filter: blur(25px) !important;
        -webkit-backdrop-filter: blur(25px) !important;
        border: 1px solid rgba(86, 88, 105, 0.28) !important;
        box-shadow: 0px 0px 18px #00000078 !important;
        transition: all 0.25s !important;
    }

    /* Estilo para botones y elementos interactivos */
    button,
    .button,
    .icon-button,
    .menu-button,
    .feedback-button,
    .new-chat-button {
        background-color: #ffffff12 !important;
        border-radius: 2em !important;
        border: 1px solid #ffffff0f !important;
        transition: all 0.25s !important;
        color: #ffffffe3 !important;
    }

    button:hover,
    .button:hover,
    .icon-button:hover,
    .menu-button:hover,
    .feedback-button:hover,
    .new-chat-button:hover {
        background: #ffffff29 !important;
    }
    
    /* Área de entrada de texto */
    .input-box,
    .prompt-textarea {
        background-color: transparent !important;
        color: #ffffff !important;
        border: none !important;
        box-shadow: none !important;
    }

    .input-area-container {
        border-radius: 2em !important;
        padding: 0 1em !important;
    }

    /* Burbujas de chat */
    .response-container,
    .query-container {
        border-radius: 1.5em !important;
        margin-bottom: 1em !important;
    }

    /* Paneles laterales y cabecera */
    .mat-drawer-container, .mat-drawer {
        background-color: transparent !important;
    }

    .header {
        border-radius: 0 !important;
        border-left: none !important;
        border-right: none !important;
        border-top: none !important;
    }

    /* Colores de texto específicos */
    a,
    .link,
    .user-name {
        color: #e0e0e0 !important;
        text-shadow: 0px 0px 15px #8ab4f86e;
    }

    .secondary-text,
    .timestamp {
        color: #ffffff8f !important;
    }

    /* Eliminación de fondos y bordes innecesarios */
    .app-root,
    .main-content > div,
    .chat-history > div {
        background: transparent !important;
        border: none !important;
    }
    
    /* Bloques de código */
    .code-block,
    pre,
    code {
        background: rgba(0, 0, 0, 0.5) !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
        border-radius: 0.5em !important;
    }
    
    /* Scrollbar */
    ::-webkit-scrollbar {
      width: 8px;
    }
    ::-webkit-scrollbar-track {
      background: #00000030;
    }
    ::-webkit-scrollbar-thumb {
      background: #ffffff29;
      border-radius: 4px;
    }
    ::-webkit-scrollbar-thumb:hover {
      background: #ffffff40;
    }

    /* Animaciones */
    @keyframes FadeInOp {
        0% { opacity: 0%; }
        100% { opacity: 100%; }
    }

    @keyframes BlurIn {
        0% { filter: blur(20px); transform: scale(1.1); }
        100% { filter: blur(0px); transform: scale(1); }
    }

    .response-container {
        animation-name: FadeInOp;
        animation-duration: 0.75s;
        animation-iteration-count: 1;
    }

    .welcome-container {
        animation-name: BlurIn;
        animation-duration: 0.9s;
        animation-iteration-count: 1;
    }
}
